readOnly goes on FormField so the Input inherits it; unlike disabled, a read-only field stays selectable and copyable.

```tsx
import { FormField, FormFieldLabel, Input } from "@salt-ds/core";
export function ClientReferenceField({ value }: { value: string }) {
  return (
    <FormField readOnly>
      <FormFieldLabel>Client reference</FormFieldLabel>
      <Input value={value} />
    </FormField>
  );
}
```

