Disable the FormField; a disabled field still lets users copy the value.

```tsx
import { FormField, FormFieldLabel, Input } from "@salt-ds/core";
export function ClientReferenceField({ value }: { value: string }) {
  return (
    <FormField disabled>
      <FormFieldLabel>Client reference</FormFieldLabel>
      <Input value={value} />
    </FormField>
  );
}
```
